[TFMDocumentType(classStr(TFMPostAdhocRegistration),'FinishPackingOrderLines')]
class TFMRequestFinishTote extends TFMRequestElement
{
    Weight weight;
    WHSContainerTypeCode	packingBox;
    NoYes					finishBox; // Is the box from Finland?
    TFMToteId				toteId;

}

Method.Source:
public TFMToteId parmToteId(TFMToteId _toteId = toteid)
{
    toteid = _toteId;
    return toteid;
}

public Weight parmWeight(Weight _weight = weight)
{
    weight = _weight;
    return weight;
}

public WHSContainerTypeCode parmPackingBox(WHSContainerTypeCode _packingBox = packingBox)
{
    packingBox = _packingBox;
    return packingBox;
}

public NoYes parmFinishBox(NoYes _finishBox = finishBox)
{
    finishBox = _finishBox;
    return finishBox;
}
